  "themes.angels.sum.1enoch.9.1": { fp: "362zwo", text: "Cuatro arcángeles miran abajo y ven el derramamiento de sangre" },
  "themes.angels.sum.Tob.5.4": { fp: "f71pzv", text: "Rafael contratado como compañero de viaje, sin ser reconocido" },
  "themes.angels.sum.af-hermas.69.3": { fp: "x2glb9", text: "Miguel pone la ley en el corazón de los creyentes" },
  "themes.angels.sum.af-ign-trallians.5.2": { fp: "918e2h", text: "Conoce los rangos y no se atribuye ninguno" },
  "themes.angels.sum.athanasius-arians-3.14.1": { fp: "4zmgle", text: "Cuando obra el Padre, ningún ángel obra" },
