  "themes.godhead.sum.philo-abraham.1.145": { fp: "2b1ev5", text: "Dos poderes en Dios: el benéfico y el que castiga" },
  "themes.godhead.sum.philo-flight.1.71": { fp: "1v2guz1", text: "«Hagamos al hombre»: habla en plural, un solo Creador" },
